// The wire enums in lib/core/data/models/wire_enums.dart are generated by tool/gen_enums.py from
// the backend's enum values. This test keeps the generated Dart file and `enums.json` (the same
// values, copied next to the other fixtures) in step, and checks the rule every enum follows: an
// unknown or missing wire value reads as null, never as a real member.

import 'package:flutter_test/flutter_test.dart';

import 'package:ghar360/core/data/models/wire_enums.dart';
import 'contract_support.dart';

void main() {
  final wire = asObject(apiFixture('enums'));

  // Each generated enum with its wire values.
  final enums = <String, List<WireEnum>>{
    'PropertyType': PropertyType.values,
    'PropertyPurpose': PropertyPurpose.values,
    'PropertyStatus': PropertyStatus.values,
    'FurnishingLevel': FurnishingLevel.values,
    'KitchenType': KitchenType.values,
    'VentilationType': VentilationType.values,
    'ListingGenderPreference': ListingGenderPreference.values,
    'ListingSharingType': ListingSharingType.values,
    'ImageCategory': ImageCategory.values,
    'VisitStatus': VisitStatus.values,
    'VisitContext': VisitContext.values,
    'BugType': BugType.values,
    'BugSeverity': BugSeverity.values,
    'BugStatus': BugStatus.values,
    'AppKey': AppKey.values,
    'AuthMethod': AuthMethod.values,
    'DevicePlatform': DevicePlatform.values,
    'AgentType': AgentType.values,
    'ExperienceLevel': ExperienceLevel.values,
    'UserRole': UserRole.values,
    'SortBy': SortBy.values,
    'PageFormat': PageFormat.values,
    'AssistantErrorCode': AssistantErrorCode.values,
    'ProfileVisibility': ProfileVisibility.values,
    'IdentifierChannel': IdentifierChannel.values,
    'IdentifierNextStep': IdentifierNextStep.values,
  };

  Object? decode(String name, Object? value) => switch (name) {
    'PropertyType' => PropertyType.fromJson(value),
    'PropertyPurpose' => PropertyPurpose.fromJson(value),
    'PropertyStatus' => PropertyStatus.fromJson(value),
    'FurnishingLevel' => FurnishingLevel.fromJson(value),
    'KitchenType' => KitchenType.fromJson(value),
    'VentilationType' => VentilationType.fromJson(value),
    'ListingGenderPreference' => ListingGenderPreference.fromJson(value),
    'ListingSharingType' => ListingSharingType.fromJson(value),
    'ImageCategory' => ImageCategory.fromJson(value),
    'VisitStatus' => VisitStatus.fromJson(value),
    'VisitContext' => VisitContext.fromJson(value),
    'BugType' => BugType.fromJson(value),
    'BugSeverity' => BugSeverity.fromJson(value),
    'BugStatus' => BugStatus.fromJson(value),
    'AppKey' => AppKey.fromJson(value),
    'AuthMethod' => AuthMethod.fromJson(value),
    'DevicePlatform' => DevicePlatform.fromJson(value),
    'AgentType' => AgentType.fromJson(value),
    'ExperienceLevel' => ExperienceLevel.fromJson(value),
    'UserRole' => UserRole.fromJson(value),
    'SortBy' => SortBy.fromJson(value),
    'PageFormat' => PageFormat.fromJson(value),
    'AssistantErrorCode' => AssistantErrorCode.fromJson(value),
    'ProfileVisibility' => ProfileVisibility.fromJson(value),
    'IdentifierChannel' => IdentifierChannel.fromJson(value),
    'IdentifierNextStep' => IdentifierNextStep.fromJson(value),
    _ => throw StateError('no decoder for $name'),
  };

  test('enums.json lists exactly the enums the app generates', () {
    expect(wire.keys.toSet(), enums.keys.toSet());
  });

  for (final entry in enums.entries) {
    group(entry.key, () {
      final values = List<String>.from(wire[entry.key] as List);

      test('has the backend wire values, in order', () {
        expect(entry.value.map((member) => member.wire), values);
      });

      test('every wire value decodes to its member and encodes back', () {
        for (final member in entry.value) {
          expect(decode(entry.key, member.wire), same(member));
        }
      });

      test('an unknown, empty, wrong-case or non-string value reads as null', () {
        for (final bad in <Object?>['__not_a_value__', '', null, 7, true]) {
          expect(decode(entry.key, bad), isNull, reason: '$bad');
        }
        final first = values.first;
        final swapped = first == first.toUpperCase() ? first.toLowerCase() : first.toUpperCase();
        if (swapped != first && !values.contains(swapped)) {
          expect(decode(entry.key, swapped), isNull, reason: swapped);
        }
      });
    });
  }

  test('VisitStatus keeps the wire values requested and reschedule_suggested', () {
    expect(VisitStatus.scheduled.wire, 'requested');
    expect(VisitStatus.rescheduled.wire, 'reschedule_suggested');
    expect(VisitStatus.fromJson('scheduled'), isNull, reason: 'the UI name is not a wire value');
    expect(VisitStatus.fromJson('rescheduled'), isNull);
  });

  test('the retired app value ghar360 is not an AppKey', () {
    expect(AppKey.fromJson('ghar360'), isNull);
    expect(AppKey.ghar.wire, 'ghar');
  });

  test('a converter writes the wire value and null', () {
    const converter = PropertyTypeConverter();
    expect(converter.toJson(PropertyType.builderFloor), 'builder_floor');
    expect(converter.toJson(null), isNull);
    expect(converter.fromJson('spaceship'), isNull);
  });
}
